#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Polygon_with_holes_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <algorithm>
#include <boost/geometry.hpp>
#include <boost/geometry/geometries/point_xy.hpp>
#include <boost/geometry/geometries/polygon.hpp>
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <random>
#include <string>
#include <vector>

namespace bg = boost::geometry;

using Epeck = CGAL::Exact_predicates_exact_constructions_kernel;
using CgalPoint = Epeck::Point_2;
using CgalPolygon = CGAL::Polygon_2<Epeck>;
using CgalPolygonWithHoles = CGAL::Polygon_with_holes_2<Epeck>;
using BgPoint = bg::model::d2::point_xy<double>;
using BgPolygon = bg::model::polygon<BgPoint, true, true>;

struct Stats {
    std::string name;
    double total_ms = 0.0;
    std::size_t calls = 0;
};

static std::vector<BgPoint> generate_convex_points(std::mt19937_64& rng,
                                                   std::size_t vertex_count,
                                                   double radius_min,
                                                   double radius_max,
                                                   double center_x,
                                                   double center_y) {
    std::uniform_real_distribution<double> angle_dist(0.0, 2.0 * M_PI);
    std::uniform_real_distribution<double> radius_dist(radius_min, radius_max);

    std::vector<double> angles(vertex_count);
    for (double& angle : angles) {
        angle = angle_dist(rng);
    }
    std::sort(angles.begin(), angles.end());

    std::vector<BgPoint> points;
    points.reserve(vertex_count);
    for (double angle : angles) {
        const double radius = radius_dist(rng);
        points.emplace_back(center_x + radius * std::cos(angle),
                            center_y + radius * std::sin(angle));
    }
    return points;
}

static BgPolygon make_bg_polygon(const std::vector<BgPoint>& points) {
    BgPolygon polygon;
    auto& outer = polygon.outer();
    outer.reserve(points.size() + 1);
    for (const auto& point : points) {
        outer.push_back(point);
    }
    if (!points.empty()) {
        outer.push_back(points.front());
    }
    bg::correct(polygon);
    return polygon;
}

static CgalPolygon make_cgal_polygon(const std::vector<BgPoint>& points) {
    std::vector<CgalPoint> cgal_points;
    cgal_points.reserve(points.size());
    for (const auto& point : points) {
        cgal_points.emplace_back(point.x(), point.y());
    }
    return CgalPolygon(cgal_points.begin(), cgal_points.end());
}

static double run_boost_intersection(const std::vector<std::pair<BgPolygon, BgPolygon>>& inputs,
                                     std::size_t rounds) {
    volatile double sink = 0.0;
    const auto start = std::chrono::steady_clock::now();
    for (std::size_t round = 0; round < rounds; ++round) {
        for (const auto& [lhs, rhs] : inputs) {
            std::vector<BgPolygon> output;
            bg::intersection(lhs, rhs, output);
            for (const auto& polygon : output) {
                sink += bg::area(polygon);
            }
        }
    }
    const auto end = std::chrono::steady_clock::now();
    if (sink == -1.0) {
        std::cerr << "Impossible sink value\n";
    }
    return std::chrono::duration<double, std::milli>(end - start).count();
}

static double run_cgal_intersection(const std::vector<std::pair<CgalPolygon, CgalPolygon>>& inputs,
                                    std::size_t rounds) {
    volatile double sink = 0.0;
    const auto start = std::chrono::steady_clock::now();
    for (std::size_t round = 0; round < rounds; ++round) {
        for (const auto& [lhs, rhs] : inputs) {
            std::list<CgalPolygonWithHoles> output;
            CGAL::intersection(lhs, rhs, std::back_inserter(output));
            for (const auto& polygon : output) {
                sink += CGAL::to_double(polygon.outer_boundary().area());
            }
        }
    }
    const auto end = std::chrono::steady_clock::now();
    if (sink == -1.0) {
        std::cerr << "Impossible sink value\n";
    }
    return std::chrono::duration<double, std::milli>(end - start).count();
}

int main(int argc, char** argv) {
    std::size_t cases = 2000;
    std::size_t vertices = 24;
    std::size_t rounds = 20;
    std::uint64_t seed = 42;

    if (argc > 1) cases = static_cast<std::size_t>(std::stoull(argv[1]));
    if (argc > 2) vertices = static_cast<std::size_t>(std::stoull(argv[2]));
    if (argc > 3) rounds = static_cast<std::size_t>(std::stoull(argv[3]));
    if (argc > 4) seed = static_cast<std::uint64_t>(std::stoull(argv[4]));

    if (vertices < 3) {
        std::cerr << "vertex count must be at least 3\n";
        return 1;
    }

    std::mt19937_64 rng(seed);
    std::uniform_real_distribution<double> center_dist(-1000.0, 1000.0);

    std::vector<std::pair<BgPolygon, BgPolygon>> boost_inputs;
    std::vector<std::pair<CgalPolygon, CgalPolygon>> cgal_inputs;
    boost_inputs.reserve(cases);
    cgal_inputs.reserve(cases);

    for (std::size_t index = 0; index < cases; ++index) {
        const double center_x = center_dist(rng);
        const double center_y = center_dist(rng);
        const auto lhs_points = generate_convex_points(rng, vertices, 40.0, 120.0, center_x, center_y);
        const auto rhs_points = generate_convex_points(rng, vertices, 40.0, 120.0, center_x + 20.0, center_y + 20.0);

        BgPolygon lhs_bg = make_bg_polygon(lhs_points);
        BgPolygon rhs_bg = make_bg_polygon(rhs_points);
        boost_inputs.emplace_back(lhs_bg, rhs_bg);
        cgal_inputs.emplace_back(make_cgal_polygon(lhs_points), make_cgal_polygon(rhs_points));
    }

    const double boost_ms = run_boost_intersection(boost_inputs, rounds);
    const double cgal_ms = run_cgal_intersection(cgal_inputs, rounds);
    const double operations = static_cast<double>(cases) * static_cast<double>(rounds);

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Convex polygon intersection benchmark\n";
    std::cout << "cases=" << cases
              << ", vertices=" << vertices
              << ", rounds=" << rounds
              << ", seed=" << seed << "\n\n";

    std::cout << std::left << std::setw(32) << "Implementation"
              << std::right << std::setw(14) << "Total (ms)"
              << std::setw(18) << "Avg/op (ms)"
              << '\n';
    std::cout << std::string(64, '-') << '\n';
    std::cout << std::left << std::setw(32) << "boost::geometry::intersection"
              << std::right << std::setw(14) << boost_ms
              << std::setw(18) << (boost_ms / operations)
              << '\n';
    std::cout << std::left << std::setw(32) << "CGAL::intersection (EPECK)"
              << std::right << std::setw(14) << cgal_ms
              << std::setw(18) << (cgal_ms / operations)
              << '\n';

    return 0;
}
